package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class GrievanceServiceImpl implements GrievanceService{
 private final GrievanceCaseRepository repo; private final GrievanceCommentRepository comments;
 public GrievanceServiceImpl(GrievanceCaseRepository r,GrievanceCommentRepository c){repo=r;comments=c;}
 public List<GrievanceCase> my(String u){return repo.findByUserIdOrderByUpdatedAtDesc(u);} public List<GrievanceCase> all(){return repo.findAllByOrderByUpdatedAtDesc();}
 public GrievanceCase get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Grievance case not found."));}
 public GrievanceCase create(GrievanceCase x,String u,String n){if(x.getSubject()==null||x.getSubject().isBlank()||x.getDescription()==null||x.getDescription().isBlank())throw new IllegalArgumentException("Subject and description are required.");x.setId(null);x.setCaseNumber(next());x.setUserId(u);x.setEmployeeName(n);x.setStatus("OPEN");x.setConfidential(true);String p=x.getPriority()==null?"MEDIUM":x.getPriority();x.setPriority(p);x.setSlaDueAt(LocalDateTime.now().plusHours("URGENT".equals(p)?4:"HIGH".equals(p)?12:"MEDIUM".equals(p)?24:72));return repo.save(x);}
 private String next(){long n=repo.count()+1;return String.format("GRV-%06d",n);}
 public GrievanceCase update(Long id,GrievanceCase x,String u,boolean m){GrievanceCase g=get(id);if(!m&&!u.equals(g.getUserId()))throw new IllegalArgumentException("Access denied.");if(!m&&!Set.of("OPEN","REOPENED").contains(g.getStatus()))throw new IllegalArgumentException("Only open or reopened cases can be edited.");g.setCategory(x.getCategory());g.setSubject(x.getSubject());g.setDescription(x.getDescription());g.setPriority(x.getPriority());g.setEvidenceReference(x.getEvidenceReference());return repo.save(g);}
 public GrievanceCase review(Long id,String status,String resolution,String assignee,String team,String u,boolean m){if(!m)throw new IllegalArgumentException("HR management access required.");if(!Set.of("OPEN","UNDER_REVIEW","INVESTIGATION","ACTION_REQUIRED","RESOLVED","CLOSED","REOPENED").contains(status))throw new IllegalArgumentException("Invalid status.");GrievanceCase g=get(id);g.setStatus(status);if(resolution!=null)g.setResolution(resolution);if(assignee!=null)g.setAssignedTo(assignee);if(team!=null&&!team.isBlank())g.setAssignedTeam(team);if("RESOLVED".equals(status)||"CLOSED".equals(status))g.setResolvedAt(LocalDateTime.now());if("REOPENED".equals(status))g.setResolvedAt(null);return repo.save(g);}
 public List<GrievanceComment> comments(Long id){get(id);return comments.findByGrievanceCase_IdOrderByCreatedAtAsc(id);}
 public GrievanceComment addComment(Long id,String u,String n,String text,boolean m){GrievanceCase g=get(id);if(!m&&!u.equals(g.getUserId()))throw new IllegalArgumentException("You cannot comment on this case.");if(text==null||text.isBlank())throw new IllegalArgumentException("Comment is required.");GrievanceComment c=new GrievanceComment();c.setGrievanceCase(g);c.setAuthorUserId(u);c.setAuthorName(n);c.setComment(text.trim());return comments.save(c);}
}
